{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "Ondansetron, which shares the carbazole-lactam core and imidazolylmethyl substituent with the query, has an absolute oral bioavailability of 0.56 (0.52-0.62) in healthy volunteers after 8 mg oral vs IV, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Theophylline, a heteroaromatic drug with amide/lactam-like features, showed absolute oral bioavailability of 98.9% for an oral syrup vs IV, supporting high oral bioavailability for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Nevirapine, a lipophilic heteroaromatic drug with an amide/lactam-like ring, has an absolute oral bioavailability of about 90% in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Ziprasidone, a lipophilic fused heterocycle containing a lactam, has an absolute oral bioavailability of 59% after a 20-mg dose with food, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Fenspiride, a small lipophilic lactam, has an absolute oral bioavailability of 90% in healthy volunteers, supporting high oral bioavailability for lactam-containing small molecules.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a carbazole-lactam with an imidazolylmethyl substituent, closely matching ondansetron, whose absolute oral bioavailability is about 56-60% in humans. Additional high-F analogues with similar heteroaromatic/lactam features (theophylline, nevirapine, ziprasidone, fenspiride) support F ≥ 20%. Low-F didanosine is mechanistically irrelevant because its poor bioavailability arises from acid-labile nucleoside structure and high polarity, features absent in the query.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact query isomer; the closest ondansetron data are for the N-linked imidazole isomer.",
    "Solubility and metabolic stability of the query are not directly measured, though physicochemical properties are favorable."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

